from rcb_traj import Session
import numpy as np
s=Session('place_fan',instance='/app/instance.json'); e=s.env
for arm in ('left','right'):
 fn=e.robot.left_plan_path if arm=='left' else e.robot.right_plan_path
 for cid in (0,1):
  try:
   pre,g=e.choose_grasp_pose(e.fan,arm,pre_dis=.10,target_dis=0,contact_point_id=cid)
   print('\n',arm,cid,'pre',np.round(pre,3),'g',np.round(g,3),flush=True)
   for label, p, kwargs in [('pre',pre,{}),('g',g,{}),('gc',g,{'constraint_pose':[1,1,1,0,0,0]})]:
    try:
     result=fn(p,**kwargs)
     print(label,'type',type(result),'status',result.get('status') if isinstance(result,dict) else result,'keys',result.keys() if isinstance(result,dict) else '',flush=True)
    except Exception as ex: print(label,'ERR',repr(ex),flush=True)
  except Exception as ex: print(arm,cid,'CAND ERR',repr(ex),flush=True)
print('joint qpos lengths',len(e.robot.left_entity.get_qpos()),len(e.robot.left_arm_joints),flush=True)
s.close()
